"""Step 45 Part E report: partE/results.md and run_info.json from results.json, train.json, ablation.json (no model)."""
import os, json, subprocess, platform, time
from . import step45_partE as E
R = json.load(open(E.P('results.json'))); T = json.load(open(E.P('train.json'))); A = json.load(open(E.P('ablation.json'))) if os.path.exists(E.P('ablation.json')) else None
f = lambda g: f"{g[0]:.3f} ({g[1]:.3f}-{g[2]:.3f})"; best = R['setA_best_single']; pas = R['pass']; passed = any(v['passed'] for v in pas.values())
names = {'logreg': 'logistic regression', 'gboost': 'gradient boosting'}
L = ['# Step 45, Part E: small learned scorer', '',
     f"**{'PASS' if passed else 'DOES NOT PASS'} the pre-registered rule** (AUROC on set A test at least 0.05 above the best single existing text scorer, CI of the paired difference excluding 0). Set A test (writer-made free text, planted-error twins vs the same case's harmless reports, {R['setA']['logreg']['cases']} cases): "
     f"logistic regression **{f(R['setA']['logreg']['auroc'])}**, gradient boosting {f(R['setA']['gboost']['auroc'])}, best single scorer ({best}) {f(R['setA'][best]['auroc'])}. Paired difference to {best}: logistic regression {R['setA_paired']['logreg']['diff'][0]:+.3f} (95% CI {R['setA_paired']['logreg']['diff'][1]:+.3f} to {R['setA_paired']['logreg']['diff'][2]:+.3f}), gradient boosting {R['setA_paired']['gboost']['diff'][0]:+.3f} ({R['setA_paired']['gboost']['diff'][1]:+.3f} to {R['setA_paired']['gboost']['diff'][2]:+.3f}). Both win on free text, so this is not template overfitting by the PREREG's definition. "
     f"**But the gain comes from the diff features, not from the existing scorers:** (exploratory, not pre-registered) a logistic regression on the five scorer outputs alone gets {f(A['logreg_scorers_only_setA_test']['auroc']) if A else 'n/a'} on set A test, below ROUGE-L alone. The advantage is the regex diff features (numbers removed / added / changed, negation words, side, category, pathology words), i.e. a number-and-category checker folded into a classifier. A pass on writer-made free text is not clinical validation.", '',
     'Pre-registration: [../PREREG.md](../PREREG.md). Code: `usmeta/step45_partE.py`, `step45_partE_report.py` (new; saved Step 5-10 scorer outputs and the Part A set imported unchanged).', '',
     '## What was trained', '',
     f"Features (14): BLEU, ROUGE-L, chrF, BERTScore (roberta-large), RaTEScore + diff features (numbers removed / added, negation-word change, side mismatch, category mismatch, pathology-word mismatch, relative size deviation, head-circumference deviation, count mismatch). Label 1 = planted error, 0 = harmless rewording of any type (small, matched, large, other: wording-only perturbations are the negatives). Trained on the DEV split of the templated benchmark ({T['n_dev_pairs']:,} pairs), hyper-parameters tuned on VAL ({T['n_val_pairs']:,} pairs; mean per-case AUROC; logistic regression C = {T['models']['logreg']['hp']}, gradient boosting depth / learning rate {T['models']['gboost']['hp']}); group-disjoint by the locked splits. Set A dev/val was used only to REPORT transfer (logistic regression {T['models']['logreg']['devval_setA_auroc']:.3f}, gradient boosting {T['models']['gboost']['devval_setA_auroc']:.3f}; best single scorer {max(T['models']['single_scorers_setA_devval'].values()):.3f}), not for tuning.", '',
     '## Test results (per-case AUROC, error vs harmless, ties 0.5; group bootstrap 1,000, seed 0)', '', '| scorer | set A test (free text) | templated test |', '|---|---|---|']
for k in ('logreg', 'gboost', 'bleu', 'rougeL', 'chrf', 'bertscore[roberta-large]', 'ratescore'):
    L.append(f"| {names.get(k, k)} | {f(R['setA'][k]['auroc'])} ({R['setA'][k]['cases']} cases) | {f(R['templated'][k]['auroc'])} ({R['templated'][k]['cases']} cases) |")
L += ['', f"On the templated test, gradient boosting reaches {R['templated']['gboost']['auroc'][0]:.3f} and logistic regression {R['templated']['logreg']['auroc'][0]:.3f}, against at most {max(R['templated'][k]['auroc'][0] for k in ('bleu', 'rougeL', 'chrf', 'bertscore[roberta-large]', 'ratescore')):.3f} for any single word scorer (templated AUROCs below 0.5 mean the word scorers rank errors above harmless rewordings, as in Steps 5-10). Set A groups: {R['setA']['logreg']['groups']}.", '']
if A:
    L += ['## Exploratory ablation (not pre-registered)', '', f"Logistic regression with only the five scorer outputs (same training, same tuning): val AUROC (templated) {A['logreg_scorers_only_setA_test']['val_auroc_templated']:.3f}, set A test {f(A['logreg_scorers_only_setA_test']['auroc'])}; with all 14 features {f(A['logreg_all_features_setA_test']['auroc'])}. Largest coefficients of the 14-feature model (standardised inputs): " + ', '.join(f"{k} {v:+.1f}" for k, v in sorted(A['coef_all_features'].items(), key=lambda kv: -abs(kv[1]))[:6]) + '.', '']
L += ['## Deviations from the PREREG', '',
      '- Set A is smaller than the PREREG (Part A results.md); the "best single existing text scorer" is chosen as the one with the highest AUROC on set A test (a conservative baseline: chosen on the test set it is compared against).',
      '- The test split was read once for this part (`test_access.log`); the ablation reused the same reports.', '',
      '## Caveats', '',
      '- Writer-made free text copies the supplied numbers verbatim, so number-diff features are very informative here; on real radiologist or VLM text (two-dimensional sizes, number words, different rounding) they may be weaker.',
      '- Planted-error twins: 1 per case, mixed fields; planted errors that change no number or category (lesion presence, position, orientation, histology) are caught only through the word scorers and the negation / pathology-word features.',
      '- The learned scorers are trained on templated text only; free-text candidates are a distribution shift, which is why the set A numbers are lower than the templated ones.', '']
open(E.P('results.md'), 'w').write('\n'.join(L)); print('wrote', len(L))
def g(*c):
    try: return subprocess.check_output(c, text=True, cwd=E.ROOT).strip()
    except Exception: return None
json.dump(dict(step='45E', git_head_at_report=g('git', 'rev-parse', '--short', 'HEAD'), prereg_commit='ca9bf2d', python=platform.python_version(), platform=platform.platform(), date=time.strftime('%Y-%m-%d'), bootstrap='group, 1000 resamples, seed 0', verdict='PASS' if passed else 'DOES NOT PASS', best_single=best), open(E.P('run_info.json'), 'w'), indent=1)
